using System;
internal sealed class PadSources {
 ulong previous;
 internal void Reset(){previous=0;}
 internal ulong Read(PadBook book,byte[] raw,uint bits,bool leftPress,bool rightPress){ulong result=bits;result&=~((1UL<<26)|(1UL<<22));if(leftPress)result|=1UL<<26;if(rightPress)result|=1UL<<22;int offset=raw[0]==0x47?20:18;for(int i=0;i<2;i++){var p=i==0?book.Left:book.Right;if(p.Action!="directions" || (bits&(i==0?0x2000000u:0x200000u))==0)continue;int x=BitConverter.ToInt16(raw,offset+i*6),y=BitConverter.ToInt16(raw,offset+i*6+2);int[] value={y,-y,-x,x};for(int d=0;d<4;d++){ulong mask=1UL<<(32+i*4+d);double threshold=32767*p.Deadzone/100.0*((previous&mask)!=0?.75:1);if(value[d]>threshold)result|=mask;}}result|=StickSources.Directions(book,raw,previous);previous=result;return result;}
 internal static void Axes(PadBook b,byte[] raw,uint bits,ref VirtualGamepad.Report r){int offset=raw[0]==0x47?20:18;for(int i=0;i<2;i++){var p=i==0?b.Left:b.Right;if((p.Action!="leftStick" && p.Action!="rightStick")||(bits&(i==0?0x2000000u:0x200000u))==0)continue;double x=BitConverter.ToInt16(raw,offset+i*6)/32767.0,y=BitConverter.ToInt16(raw,offset+i*6+2)/32767.0,m=Math.Sqrt(x*x+y*y),dead=p.Deadzone/100.0,scale=m<=dead?0:Math.Min(1,(m-dead)/(1-dead))/m;short ax=(short)Math.Round(x*scale*32767),ay=(short)Math.Round(y*scale*32767);if(p.Action=="leftStick"){r.LX=ax;r.LY=ay;}else{r.RX=ax;r.RY=ay;}}}
 internal static void Test(){var b=new PadBook();b.Left.Action="directions";b.Left.Click="binding";b.Left.PressAction=new BindingAction{Kind="keyboard",Chord="Space"};var raw=new byte[48];raw[0]=0x45;var p=new PadSources();uint touch=0x2000000;Array.Copy(BitConverter.GetBytes((short)20000),0,raw,20,2);ulong up=InputCatalog.SourceMask("LP_UP");if((p.Read(b,raw,touch,false,false)&up)==0)throw new Exception("Pad up not mapped");Array.Copy(BitConverter.GetBytes((short)0),0,raw,20,2);if((p.Read(b,raw,touch,false,false)&up)!=0)throw new Exception("Pad center must release");var e=new BindingEngine(b);e.Step(p.Read(b,raw,touch,false,false),0);if(!e.Step(p.Read(b,raw,touch,true,false),1).Contains("KeyDown vk=32"))throw new Exception("Pad pressure custom binding");if(!e.Step(p.Read(b,raw,touch,false,false),2).Contains("KeyUp vk=32"))throw new Exception("Pad pressure release");b.Left.Action="rightStick";Array.Copy(BitConverter.GetBytes((short)32767),0,raw,18,2);var r=VirtualGamepad.ConvertReport(b,raw,touch);if(r.RX!=32767 || r.RY!=0)throw new Exception("Pad stick scaling");r=VirtualGamepad.ConvertReport(b,raw,0);if(r.RX!=0)throw new Exception("Lift must release stick");b.LeftStick.Action="wasd";Array.Copy(BitConverter.GetBytes((short)20000),0,raw,12,2);if((p.Read(b,raw,0,false,false)&InputCatalog.SourceMask("LS_UP"))==0)throw new Exception("Stick WASD missing");Array.Copy(BitConverter.GetBytes((short)0),0,raw,12,2);if((p.Read(b,raw,0,false,false)&InputCatalog.SourceMask("LS_UP"))!=0)throw new Exception("Stick WASD stuck");Probe.Say("PAD MAPPING PASS: direction/center, pressure action/release, stick scaling/lift.");}
}
